code.cpp:
class Solution {
public:
    vector<string> findRepeatedDnaSequences(string s) {
        vector<string> res;
        if (s.length() < 10) return res;

        vector<int> cnt(1048576, 0);
        int hash = 0;

        for (int i = 0; i < s.length(); ++i) {
            int val = 0;
            if (s[i] == 'A') val = 0;
            else if (s[i] == 'C') val = 1;
            else if (s[i] == 'G') val = 2;
            else if (s[i] == 'T') val = 3;

            hash = ((hash << 2) & 0xFFFFF) | val;

            if (i >= 9) {
                if (++cnt[hash] == 2) {
                    res.push_back(s.substr(i - 9, 10));
                }
            }
        }
        return res;
    }
};
